import React from 'react';
import NormalButton from '../../ui/NormalButton';
import mixpanel from "mixpanel-browser";

const TabsSectionI = () => {

  const [activeTab, setActiveTab] = React.useState("tab1");
  const trackButtonClick = (Property) => {
    mixpanel.track('External Link', {
    Name : Property,
    Property: Property, });
  };
  
    return (
      <main className="lg:flex">
        <ul className='lg:w-[40rem] lg:px-10'>
          <li className={` transition-all mb-8 px-6 ${activeTab === 'tab1' ? "border-primary border-r-4  text-primary" : "text-dark-blue-greenish cursor-pointer"}`}
            onClick={() => setActiveTab('tab1')}>
            <h3 className='text-2xl'>
            Write your talent needs  
            </h3>
            <p className='font-normal text-lg mt-2'>
            Tell Clous Peer what you need and see how your tailored job opening is created.
            </p>
          </li>
          <li className={`transition-all my-8 px-6 ${activeTab === 'tab2' ? 'border-primary border-r-4 text-primary' : 'text-dark-blue-greenish cursor-pointer'}`}
            onClick={() => setActiveTab('tab2')}>
            <h3 className='text-2xl'>
            Create, publish, and share
            </h3>
            <p className='font-normal text-lg mt-2'>
            In 3 clicks, you can create, publish and share your job opening without friction.            </p>
          </li>
          <li className={`transition-all my-8 px-6 ${activeTab === 'tab3' ? 'border-primary border-r-4 text-primary border-spacing-12' : 'text-dark-blue-greenish cursor-pointer'}`}
            onClick={() => setActiveTab('tab3')}>
            <h3 className='text-2xl'>
            Start interviewing
            </h3>
            <p className='font-normal text-lg mt-2'>
            Get ready to interview pre-qualified as soon as they apply to your job opening.
            </p>
          </li>
          <li className={`transition-all my-8 px-6 ${activeTab === 'tab4' ? 'border-primary border-r-4 text-primary border-spacing-12' : 'text-dark-blue-greenish cursor-pointer'}`}
            onClick={() => setActiveTab('tab4')}>
            <h3 className='text-2xl'>
            Recycle talent efforts            
            </h3>
            <p className='font-normal text-lg mt-2'>
            If you have already interviewed qualified candidates, there’s no need to source more talent!            
            </p>
          </li>
        </ul>
  
        <section className="w-[44rem] mx-auto"> 
          {activeTab === 'tab1' && <section className='flex flex-col' >
          
            <img src="https://clous.s3.eu-west-3.amazonaws.com/images/ClousPeer.webp" className="rounded-xl  overflow-hidden" alt="ClousH AI Peer"/>

              <NormalButton name="Try our Beta" linkUrl="https://demo.clous.app" className='flex mt-4 mx-auto'
            onClick={() => trackButtonClick("Demo")}/>
          </section> }
          {activeTab === 'tab2' && <section className='flex flex-col' >
          
            <img src="https://clous.s3.eu-west-3.amazonaws.com/images/ClousJO.webp" className="rounded-xl  overflow-hidden" alt="ClousH Home"/>
              <NormalButton name="Get quote" linkUrl="/get-quote" className='flex mt-4 mx-auto'
            onClick={() => trackButtonClick("Demo")}/>
          </section> }
          {activeTab === 'tab3' && <section className='flex flex-col' >
          
            <img src="https://clous.s3.eu-west-3.amazonaws.com/images/ClousHome.webp" className="rounded-xl  overflow-hidden" alt="ClousH Home"/>

              <NormalButton name="Request live demo" linkUrl="/contact" className='flex mt-4 mx-auto'
            onClick={() => trackButtonClick("Demo")}/>
          </section> }
          {activeTab === 'tab4' && <section className='flex flex-col' >
          
            <img src="https://clous.s3.eu-west-3.amazonaws.com/images/ClousATS.webp" className="rounded-xl  overflow-hidden" alt="ClousH Sourcing"/>
              <NormalButton name="Contact sales" linkUrl="/contact" className='flex mt-4 mx-auto'
            onClick={() => trackButtonClick("Demo")}/>
          </section> }
        
        </section>
      </main>
    );
  };
  
  export default TabsSectionI;
  