import { Card, Input, Select, Textarea, Option } from "@material-tailwind/react";
import { useState } from "react";
import NormalButton from "../../ui/NormalButton";
import { Link } from "react-router-dom";
import ModalCheck from "../../ui/Modal";
import { IoPlayCircle } from "react-icons/io5";
import axios from "axios";
import mixpanel from "mixpanel-browser";
  
  export default function ContactPage({modalIsOpen, setModalIsOpen}) {
    const trackButtonClick = (Property) => {
      mixpanel.track('External Link', {
      Name : Property,
      Property: Property, });
    };
    const [errors, setErrors] = useState({}); // Nuevo estado para mensajes de error

    const [formData, setFormData] = useState({
      first: "",
      last: "",
      email: "",
      subject: "", // Añade el campo subject en el estado del formulario
      message: "",
    });
    const { first, last, email, message, subject } = formData;
    const subjectOptions = [
      { value: "Request live demo", label: "Request live demo" },
      { value: "Contact sales", label: "Contact sales" },
      { value: "Redeem sign up code", label: "Redeem sign up code" },
      { value: "Onboarding aid", label: "Onboarding aid" },
      { value: "1:1 consulting sessionss", label: "1:1 consulting sessions" },
      { value: "Paid pilot", label: "Paid pilot" },
    ];
    const handleSelect = (selectedValue) => {
      setFormData({ ...formData, subject: selectedValue });
    };
    const onChange = (e) => {
      setFormData({ ...formData, [e.target.name]: e.target.value });
    };
  
    const onSubmit = async (e) => {
      e.preventDefault();
  
      try {
        const response = await axios.post(`${process.env.REACT_APP_API_URL}/api/formularios/contact`, formData);
  
        // Actualiza el estado 'status' según la respuesta del servidor
        setFormData({ ...formData, status: "success" });
  
        console.log("Response from server:", response.data);
  
        // Puedes realizar otras acciones según la respuesta, como mostrar un mensaje de éxito
      } catch (error) {
        // Maneja los errores aquí
        console.error("Error sending data:", error.response.data.email);
  
        // Muestra mensajes de error específicos si la respuesta indica un error
        if (error.response) {
          setErrors(error.response.data.errors); // Suponiendo que el servidor devuelve un objeto 'errors'
        } else {
          setErrors({ general: "An unexpected error occurred." }); // Error no relacionado con la respuesta del servidor
        }
  
        // Actualiza el estado 'status' según la respuesta del servidor
        setFormData({ ...formData, status: "error" });
      }
    };
  
    
    const openModal = () => {
      // ... Lógica para abrir el modal ...
      setModalIsOpen(true);
    };
  
    const closeModal = () => {
      // ... Lógica para cerrar el modal ...
      setModalIsOpen(false);
    };
  
    return (
      <main className="bg-[#fafafa] lg:flex justify-between gap-4 lg:py-16 max-w-8xl ">
        <section className="max-w-2xl text-xl flex flex-col 
        ">
          <h1
            className=" font-semibold tracking-tight
               dark:text-white text-7xl mb-3"
          >
            We build relationships
          </h1>
          <p>
            At Clous, we believe that maintaining close, personal contact with
            each of our customers is fundamental to our mission.
          </p>
          <div className="grid md:flex md:justify-center items-center gap-4 text-lg">

          <NormalButton name="Try our Beta" linkUrl="https://demo.clous.app"
              onClick={() => trackButtonClick("Demo")}/>
        <div onClick={openModal} className="flex gap-2 items-center cursor-pointer">
          <IoPlayCircle className="w-5 h-5"/> Watch our demo
        </div>
      </div>
     
        </section>
        <section>
          <Card
            color="transparent"
            className="lg:mx-auto max-w-xl "
            shadow={false}
            >
            {formData.status === "success" ? (
              <div>
                <h3 className="text-xl lg:text-2xl">Thanks for reaching out!</h3>
                <p className="text-sm lg:text-lg">
                  We're already working super hard to get back to you as soon as possible. In the meantime, you can{" "}
                  <a href="https://www.clous.app/blog" className="text-primary border-b border-primary">
                    check our blog articles.
                  </a>
                </p>
              </div>
            ) : (
           
          
            <form onSubmit={(e) => onSubmit(e)} className="mb-2">
              <div className="mb-2 flex flex-col gap-6">
                <div className="flex gap-4">
                  <Input
                    id="first"
                    name="first"
                    value={first}
                    onChange={(e) => onChange(e)}
                    type="text"
                    required
                    label="First name"
                    color="orange"
                  />{" "}
                  <Input
                    id="last"
                    name="last"
                    value={last}
                    onChange={(e) => onChange(e)}
                    type="text"
                    required
                    label="Last name"
                    color="orange"
                  />{" "}
                </div>
                <Input
                  value={email}
                  onChange={(e) => onChange(e)}
                  name="email"
                  type="email"
                  required
                  label="Company Email"
                  color="orange"
                />
                
                <Select
  name="subject"
  value={subject}
  onChange={handleSelect} // Usa la función handleSelect
  label="What do you need?"
  color="orange"
>
  {subjectOptions.map((option) => (
    <Option key={option.value} value={option.value}>
      {option.label}
    </Option>
  ))}
</Select>
                <Textarea
                  id="message"
                  name="message"
                  value={message}
                  required
                  onChange={(e) => onChange(e)}
                  label="Why are you contacting us?"
                  color="orange"
                ></Textarea>
              </div>
              <div
                className="max-w-screen-sm text-sm text-left newsletter-form-footer
           dark:text-gray-300"
              >
                By clicking you agree to our{" "} 
                <Link
                  to="/privacy"
                  className="text-primary"
                >
                Privacy Policy.
                </Link>
              </div>
  
              <button type="submit" className="flex justify-start mr-auto font-semibold mt-2">
                <NormalButton name="Submit"  />

              </button>
            </form>
        )}
          </Card>
        </section>
        <ModalCheck
         isOpen={modalIsOpen}
         onRequestClose={closeModal}
         />
      </main>
    );
  }
  