import { BrowserRouter as Router} from "react-router-dom";
import store from "./store";
import { HelmetProvider } from "react-helmet-async";
import { Provider } from "react-redux";
import AnimatedRoutes from "Routes";
import ReactGA from "react-ga4";
import mixpanel from "mixpanel-browser";

function App() {
  const TRACKING_ID = "G-S5Q10GPJ66"; 
  ReactGA.initialize(TRACKING_ID);
  ReactGA.send({ hitType: "pageview", page: window.location.pathname + window.location.search, title:'Home' });
  
  mixpanel.init('4477d9caa0e54978f32649f86571907f', {debug: true, persistence: 'localStorage'});
  return (
    
    <HelmetProvider>
  
      <Provider store={store}>
        <Router>
    <AnimatedRoutes />

        </Router>
      </Provider>
    </HelmetProvider>
  );
}




export default App;
