import { Link } from "react-router-dom";
import collaboration from "assets/img/clous.app_collaboration.json";
import Lottie from "lottie-react";
import FeatureCard from "../../ui/FeatureCard";
import TextButton from "../../ui/TextButton";

function SectionX() {

  return (
    <section className="pb-16">
      <div className="lg:flex justify-between">
        <div className="mt-20 lg:w-[40rem]">
          <h2 className="text-3xl lg:text-5xl">
          Engage with candidates, save time
          </h2>
          <p className="my-2 font-normal lg:text-lg">
          Engaging with candidates brings you many benefits in the long term: not having to re-do interviews, saving time to source candidates and many more. Engaged candidates provides an unlimited talent pool.
          </p>
          <div className="my-5 flex">

            <Link to="/register" className=" text-primary"

        >
          <TextButton name="Start attracting talent today" />
        </Link>
          </div>
        </div>
        <div className="lg:w-[40rem] h-full">

        <Lottie animationData={collaboration} />
        </div>

      </div>
      <section className="grid gap-8 lg:grid-cols-3 grid-cols-1 ">
        <FeatureCard
        icon={ <img className='w-6' src='https://clous.s3.eu-west-3.amazonaws.com/icons/icon-7.webp' alt="Clous Icons"/>} 
        title="Pre-qualified candidates"
        description="Stop collaborationing resumes from unqualified candidates."
        />
        <FeatureCard
        icon={ <img className='w-6' src='https://clous.s3.eu-west-3.amazonaws.com/icons/icon-8.webp' alt="Clous Icons"/>} 
        title="Reduce time to hire"
        description="Adopt agile methodologies and hire on the spot! "
        />


        <FeatureCard
        icon={ <img className='w-6' src='https://clous.s3.eu-west-3.amazonaws.com/icons/icon-9.webp' alt="Clous Icons"/>} 
        title="x10 better experience"
        description="We deliver a humanizing hiring process to engage candidates."
        />          
  
      </section>
    </section>
  );
}

export default SectionX;
