import FeatureCard from "../ui/FeatureCard";
function Uvp() {

  return (
    <main className="py-16">
      <h2 className="md:text-5xl md:text-center text-3xl  md:max-w-lg md:mx-auto mb-12">
      Start interviewing in days, not weeks
      </h2>
     
      <section className="grid gap-8 lg:grid-cols-3 grid-cols-1">
        <FeatureCard
        icon={ <img className='w-6' src='https://clous.s3.eu-west-3.amazonaws.com/icons/icon-1.webp' alt="Clous Icons"/>} 
        title="Collaborative recruitment"
        description="Share your job opening data with your collaborators during the hiring process. Build alignment between all your stakeholders!"
        />
        <FeatureCard
        icon={ <img className='w-6' src='https://clous.s3.eu-west-3.amazonaws.com/icons/icon-2.webp' alt="Clous Icons"/>} 
        title="Qualified candidates"
        description="Define what filters you want to qualify candidates before the interview. Engage with candidates thanks to Talent Loops."
        />
        <FeatureCard
        icon={ <img className='w-6' src='https://clous.s3.eu-west-3.amazonaws.com/icons/icon-3.webp' alt="Clous Icons"/>} 
        title="Personalized feedback"
        description="Don’t take candidate ghosting as the norm, use ClousH to automate personalized feedback to every job opening candidate."
        />          
  
      </section>
    </main>
  );
}

export default Uvp;
