import NormalButton from "../../ui/NormalButton";
import mixpanel from "mixpanel-browser";
import { IoPlayCircle } from "react-icons/io5";
import ModalCheck from "../../ui/Modal";

export default function HeroClous ({modalIsOpen, setModalIsOpen}) {

  const trackButtonClick = (Property) => {
    mixpanel.track('External Link', {
    Name : Property,
    Property: Property, });
  };

  const openModal = () => {
    // ... Lógica para abrir el modal ...
    setModalIsOpen(true);
  };

  const closeModal = () => {
    // ... Lógica para cerrar el modal ...
    setModalIsOpen(false);
  };

  return (
    <section className="py-16 flex gap-4">
        <div className="w-full">
            <h1 className="text-4xl lg:text-7xl">
            People-first technology to hire at scale
            </h1>
            <p className="my-2 font-normal text-lg lg:text-xl">
            We have both candidates and HR professionals as top of mind when we develop our product. We believe in efficiency leading to human connections.
            </p>
            <div className="my-5 sm:flex flex-1 text-lg gap-x-2 ">
  
          <NormalButton name="Try our Beta" linkUrl="https://demo.clous.app"
              onClick={() => trackButtonClick("Demo")}/>
        <div onClick={openModal} className="flex gap-2 items-center cursor-pointer">
          <IoPlayCircle className="w-5 h-5"/> Watch our demo
        </div>
            </div>
          </div>
          <img width={480} src="https://clous.s3.eu-west-3.amazonaws.com/images/ClousPeer.webp" className="rounded-lg" alt="Clous dashboard and welcome"/>
         
          <ModalCheck
        isOpen={modalIsOpen}
        onRequestClose={closeModal}
        />
    </section>
  );
}

