import React, { useState } from 'react';
import NormalButton from '../../ui/NormalButton';

const TabSectonI = () => {
  const [activeTab, setActiveTab] = useState('tab1');

  return (
    <main className="lg:flex">
      {/* Tabs */}
      <ul className='lg:w-[32rem] lg:px-10'>
        <li className={`transition-all mb-8 px-6 ${activeTab === 'tab1' ? "border-primary border-r-4  text-primary" : "text-dark-blue-greenish cursor-pointer"}`}
          onClick={() => setActiveTab('tab1')}>
          <h3 className='text-2xl'>
          Blind trust

          </h3>
          <p className='font-normal text-lg mt-2'>
          We trust each other by default, and fight everyday to not lose it.

Infinite causality
          </p>
        </li>
        <li className={`transition-all my-8 px-6 ${activeTab === 'tab2' ? 'border-primary border-r-4 text-primary' : 'text-dark-blue-greenish cursor-pointer'}`}
          onClick={() => setActiveTab('tab2')}>
          <h3 className='text-2xl'>
          Infinite causality
          </h3>
          <p className='font-normal text-lg mt-2'>
          We believe that acting in the present will cause future impact.
          </p>
        </li>
        <li className={`transition-all my-8 px-6 ${activeTab === 'tab3' ? 'border-primary border-r-4 text-primary border-spacing-12' : 'text-dark-blue-greenish cursor-pointer'}`}
          onClick={() => setActiveTab('tab3')}>
          <h3 className='text-2xl'>
          Urgent optimism
          </h3>
          <p className='font-normal text-lg mt-2'>
          Doing the right things today will have a positive future outlook.
          </p>
        </li>
      </ul>

      {/* Content */}
      <section className="w-[40rem] mx-auto">
        {activeTab === 'tab1' && <section className='flex flex-col' >
        
          <img src="https://clous.s3.eu-west-3.amazonaws.com/images/sourcing.webp" alt="Clous Home"  className="rounded-xl overflow-hidden "/>
            <NormalButton name="Read Culture Statement" linkUrl="https://clous-app.notion.site/Culture-Statement-4fc02393176146148c1c73638e643c21?pvs=4" target="_blank" className='flex mt-4 mx-auto'/>
        </section> }
        {activeTab === 'tab2' && <section className='flex flex-col' >
        
          <img src="https://clous.s3.eu-west-3.amazonaws.com/images/pay-gap.webp" alt="Clous Peer" className="rounded-xl  overflow-hidden"/>
   

            <NormalButton name="Visit our jobs" linkUrl="https://clous-app.notion.site/Come-do-the-best-work-of-your-life-at-Clous-4283b0596d7b498ba955772f714a66b8?pvs=4" className='flex mt-4 mx-auto'/>
        </section> }
        {activeTab === 'tab3' && <section className='flex flex-col' >
        
          <img src="https://clous.s3.eu-west-3.amazonaws.com/images/ClousPeer.webp" alt="Clous Sourcing"  className="rounded-xl  overflow-hidden"/>

            <NormalButton name="Try our Beta"  linkUrl="https://demo.clous.app" className='mx-auto flex mt-4'/>
¡        </section> }
      
      </section>
    </main>
  );
};

export default TabSectonI;