import { CameraOff, Cpu, Gift, Heart, ShieldOff, UserX } from "lucide-react";
import { Link } from "react-router-dom";
import TextButtonWhite from "../ui/TextButtonWhite";
import mixpanel from "mixpanel-browser";

const Ctaband = () => {
  const trackButtonClick = (Property) => {
    mixpanel.track('External Link', {
    Name : Property,
    Property: Property, });
  };

  return (

    <main className="overflow-hidden rounded-lg bg-primary p-16 my-16 text-secondary">
      <section >
        <h2 className="text-3xl lg:text-5xl ">
        How is Clous different?
        </h2>
        <div className="grid grid-cols-3 mt-4 mb-6 font-normal text-lg gap-4">
        <p className='flex gap-2 items-start leading-6'><Heart className='w-5 h-5'/>
                We accelerate face-to-face <br/>  connections
        </p>
        <p className='flex gap-2 items-start leading-6'><UserX className='w-5 h-5'/>
                We don’t classify talent <br/>  on social scoring
        </p>
        <p className='flex gap-2 items-start leading-6'><CameraOff className='w-5 h-5'/>
                We enable live interviewing, <br/>  not one-way interviews
        </p>
        <p className='flex gap-2 items-start leading-6'><Gift className='w-5 h-5'/>
                We don’t charge for <br/>  our services
        </p>
        <p className='flex gap-2 items-start leading-6'><ShieldOff className='w-5 h-5'/>
                We don’t charge you more <br/>  as you grow
        </p>
        <p className='flex gap-2 items-start leading-6'><Cpu className='w-5 h-5'/>
                AI is critical to <br/> our solution
        </p>
        </div>
        <Link to="https://demo.clous.app" target="_blank" className="inline-flex"
                onClick={() => trackButtonClick("Demo")}
        >
         <TextButtonWhite name="Request live demo"/>
        </Link>
      </section>
     <section></section>
    </main>
)
  }
export default Ctaband;
