import { Link } from "react-router-dom";
import mixpanel from "mixpanel-browser";
import TextButton from "../../ui/TextButton";
import NormalButton from "../../ui/NormalButton";

function HeroTeam() {
  const trackButtonClick = (Property) => {
    mixpanel.track('External Link', {
    Name : Property,
    Property: Property, });
  };

  
  return (
    <section className="py-16 max-w-8xl overflow-hidden lg:flex justify-between gap-8">
        <div >
            <h1 className="text-5xl lg:text-7xl">
            Come do the best work of your life
            </h1>
            <p className="mt-3 text-lg lg:text-xl font-normal lg:max-w-2xl">
              Our clients come first, our product too.
               We give our users the voice to iterate our beloved product.
            </p>
            <div className="grid md:flex mt-4 items-center gap-4 text-lg">
 
          <NormalButton name="Try our Beta" linkUrl="https://demo.clous.app"
              onClick={() => trackButtonClick("Demo")}/>
        <Link 
              className="inline-flex text-primary"

              to="/partners#programs"
               >
              
              <TextButton name="Join our programs"/>
            </Link>
      </div>
        </div>
          <img width={640} className="rounded-xl lg:block hidden" src="https://clous.s3.eu-west-3.amazonaws.com/images/deiFunnel.webp" alt="Clous team"/>

    </section>
  );
}

export default HeroTeam;
