import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import Icon from './BaseIcon';

const NormalButton = ({ name, color, size, linkUrl, className }) => {
  const [isOver, setIsOver] = useState(false);

  const buttonClasses = `
    rounded-lg shadow-none hover:shadow-none flex text-lg bg-primary px-3 py-1.5 text-secondary hover:bg-primary font-semibold
    ${className || ''}  // Agregar la clase proporcionada por el usuario
  `;

  return (
    <Link
      to={linkUrl}
      className={buttonClasses}
      onMouseOver={() => setIsOver(true)}
      onMouseOut={() => setIsOver(false)}
    >
      {name}
      {isOver && <Icon name="ArrowRight" color="#fff" />}
      {!isOver && <Icon name="ChevronRight" color="#fff" />}
    </Link>
  );
};

export default NormalButton;
