import NormalButton from "../ui/NormalButton";
import mixpanel from "mixpanel-browser";
import { IoPlayCircle } from "react-icons/io5";
import ModalCheck from '../ui/Modal';

function Header({modalIsOpen, setModalIsOpen}) {
  const trackButtonClick = (Property) => {
    mixpanel.track('External Link', {
    Name : Property,
    Property: Property, });
  };


  const openModal = () => {
    // ... Lógica para abrir el modal ...
    setModalIsOpen(true);
  };

  const closeModal = () => {
    // ... Lógica para cerrar el modal ...
    setModalIsOpen(false);
  };
  const renderButtons = () => {
    return (
      <div className="grid md:flex md:justify-center items-center gap-4 text-lg">

          <NormalButton name="Try our Beta" linkUrl="https://demo.clous.app"
              onClick={() => trackButtonClick("Demo")}/>
        <div onClick={openModal} className="flex gap-2 items-center cursor-pointer">
          <IoPlayCircle className="w-5 h-5"/> Watch our demo
        </div>
      </div>
    );
  };

  return (
    <main className="py-16 md:flex justify-center mt-20 items-center md:text-center">
      <section className="lg:px-32 h-full">
        <h1 className="font-bold text-4xl md:text-7xl">
          Efficient recruiting for hiring teams
        </h1>
        <p className="font-normal text-lg md:text-xl mt-2 mb-4 mx-auto">
          Reviewing hundreds of resumes, weeks until the first interview and impossible to give feedback to candidates. Is that you?
        </p>
        {renderButtons()}
      </section>


      <ModalCheck
        isOpen={modalIsOpen}
        onRequestClose={closeModal}
        />
    </main>
  );
}

export default Header;
