import Icon from "../ui/BaseIcon"
import FeatureCard from "../ui/FeatureCard"
import TextButton from "../ui/TextButton"
import mixpanel from "mixpanel-browser";

function Programs() {
  const trackButtonClick = (Property) => {
    mixpanel.track('Program Link', {
    Name : Property,
    Property: Property, });
  };
  return (
    <main className="py-16 text-center">
      <header>
        <h2 className="text-3xl lg:text-5xl ">
        Explore our programs
        </h2>

      </header>
      <section id="programs" className="grid gap-4 row-gap-6 md:grid-cols-2 xl:grid-cols-4 my-5 text-left">
    

        <FeatureCard
        icon={<Icon name="Medal"/>} 
        title="Solution Partners"
        description="The benefits of partnering with us: including HR advice sessions, warm leads, and discounts."
        textBtn={<TextButton name="Read more"/>}
        buttonLink="https://clous-app.notion.site/Solution-Partners-2b31b5b9fc544bcaa0d9ff986434d7d1?pvs=4"
        onButtonClick={() => trackButtonClick("Solution Partners")} 
         />
       

        <FeatureCard
        icon={<Icon name="FaStaylinked"/>} 
        title="Referral Program"
        description="This program offers free access to the Clous platform and its latest features to HR professionals."
        textBtn={<TextButton name="Read more"/>}
        buttonLink="https://clous-app.notion.site/Solution-Partners-2b31b5b9fc544bcaa0d9ff986434d7d1?pvs=4"
        onButtonClick={() => trackButtonClick("Referral")} 
        />

        <FeatureCard
        icon={<Icon name="FaRocketchat"/>} 
        title="Startups Program"
        description="Being a startup ourselves, we know how hard it can be to grow your organization. This program is for you."
        textBtn={<TextButton name="Apply now"/>}
        buttonLink="/startup#startupform"
        />

        <FeatureCard
        icon={<Icon name="BsShieldLock"/>} 
        title="HR Supporters"
        description="Our referral program offers benefits such as HR advice sessions, a special customer experience channel."
        textBtn={<TextButton name="Apply now" />}
        buttonLink="/hrteams#hrsupportform"
        />
           
      </section>
    </main>
  )
}

export default Programs