import { Route, Routes, useLocation, Navigate } from "react-router-dom";
import Error404 from "containers/errors/Error404";
import Home from "containers/pages/Home";
import Team from "containers/pages/about/Team";
import Business from "containers/pages/solutions/Enterprise";
import Startups from "containers/pages/solutions/Startups";
import HrTeams from "containers/pages/solutions/HrTeams";
import Contact from "containers/pages/resources/Contact";
import Terms from "containers/pages/legal/Terms";
import Privacy from "containers/pages/legal/Privacy";
import Disclaimer from "containers/pages/legal/Disclaimer";

import { AnimatePresence } from "framer-motion";
import Mision from "containers/pages/about/Mision";
import Partner from "containers/pages/about/Partner";
import Pricing from "containers/pages/resources/Pricing";

import ThankYouPage from "containers/pages/conect/ThankYouPage";

import Auth from "containers/pages/conect/Auth";


import CookieBanner from "containers/pages/CookieBanner";
import ClousH from "./containers/pages/product/ClousH";
import GetQuote from "./containers/pages/resources/Quote";
import RoiPage from "./containers/pages/resources/RoiPage";
import Editorial from "./containers/pages/editorial/Editorial";
import News from "./containers/pages/editorial/news/News";
import NewsDetails from "./containers/pages/editorial/news/NewsDetails";
import Guides from "./containers/pages/editorial/guides/Guides";
import LeadGenerations from "./containers/pages/editorial/guides/LeadGen";
import Blog from "./containers/pages/editorial/blog/Blog";
import BlogDetails from "./containers/pages/editorial/blog/BlogDetails";
import HrTalks from "./containers/pages/editorial/hrtalks/HrTalks";
import HRTalksDetails from "./containers/pages/editorial/hrtalks/HRTalksDetails";

function AnimatedRoutes() {
  
  const location = useLocation()

  return (
    <AnimatePresence >
    
      
    <CookieBanner />
      {/* Other routes */}

    <Routes location={location} key={location.pathname} >
      {/* 404 Display */}
      {/* Home Display */}
      <Route exact path="/" element={<Home />} />
      
      <Route path="/team" element={<Team />} />     
      <Route path="/mission" element={<Mision />} />
      <Route path="/partners" element={<Partner/>} />

      <Route path="/contact" element={<Contact />} />
      <Route path="/pricing" element={<Pricing />} />
      <Route path="/get-quote" element={<GetQuote />} />
      <Route path="/roi-calculator" element={<RoiPage />} />

      <Route path="/cloush" element={<ClousH />} />

      <Route path="/hiring-teams" element={<HrTeams />} />
      <Route path="/startup" element={<Startups/>} />
      <Route path="/enterprise" element={<Business />} />

      <Route path="/terms" element={<Terms />} />
      <Route path="/privacy" element={<Privacy />} />
      <Route path="/disclaimer" element={<Disclaimer />} />

      <Route path="/thank-you" element={<ThankYouPage/>} />
      <Route path="/sign-on" element={<Auth />} />

      <Route path="/editorial" element={<Editorial/>} />

      <Route path="/blog" element={<Blog />} />
      <Route path="/blog/:slug" element={<BlogDetails />} />

      <Route path="/news-room" element={<News/>} />
      <Route path="/news-room/:slug" element={<NewsDetails />} />

      <Route path="/guides" element={<Guides/>} />
      <Route path="/guides/:slug" element={<LeadGenerations/>} /> 


      <Route path="/hr-talks" element={<HrTalks/>} />
      <Route path="/hr-talks/:slug" element={<HRTalksDetails />} />

   {/*    <Route path="/research" element={<Research/>} />
      <Route path="/research/:slug" element={<ResearchDetails/>} /> */}
{/*       <Route path="/help-center" element={<HelpCenter />} />
 */}      <Route 
          path="/press" 
          element={<Navigate to="/" replace/>} 
      />
      <Route 
          path="/hrteams" 
          element={<Navigate to="/hiring-teams" />} />
      <Route
          path="/clousr"
          element={<Navigate to="/cloush" replace />}
        />
      <Route
          path="/register"
          element={<Navigate to="/sign-on" replace />}
        />

      <Route path="/*" element={<Error404 />} />
    </Routes>
    </AnimatePresence>
  );
}
export default AnimatedRoutes;
