import { Link } from "react-router-dom";
import { useEffect, useState } from "react";
import moment from "moment";
import axios from "axios";

function BlogList() {
  const [blogList, setBlogList] = useState([]);
  const [categoryList, setCategoryList] = useState([]);
  const [selectedCategory, setSelectedCategory] = useState(null); // Nuevo estado para almacenar la categoría seleccionada
  axios.defaults.withCredentials = true;

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await axios.get(`${process.env.REACT_APP_API_URL_2}/api/blog/list`, { withCredentials: true });
        setBlogList(Array.isArray(response.data.blogs) ? response.data.blogs : []);
      } catch (error) {
        console.error('Error fetching blog:', error);
      }
    };
  
    fetchData();
  }, []);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await axios.get(`${process.env.REACT_APP_API_URL_2}/api/blog/categories/list`, { withCredentials: true });
        setCategoryList(response.data);
      } catch (error) {
        console.error('Error fetching blog:', error);
      }
    };
 
    fetchData();
  }, []);

  // Función para filtrar los blogs por categoría
  const filterBlogsByCategory = (category) => {
    setSelectedCategory(category);
  };

  return (
    <main>
     <section className="flex justify-center mb-12">
      {categoryList &&
        categoryList.map((cat, index) => (
          <div key={index} className="flex mx-2">
            <button
              className={`border rounded-full px-3 py-2 ${cat.name === selectedCategory ? 'bg-primary text-white ' : 'hover:bg-primary hover:text-white'}`}

              onClick={() => filterBlogsByCategory(cat.name)}
            >
              {cat.name}
            </button>
          </div>
        ))}
    </section>
    <section className="grid md:grid-cols-2 xl:grid-cols-3 gap-8">
      {blogList &&
        blogList
          .filter((post) => {
            const postCategories = post.categories || (post.category ? [post.category] : []); // Manejar categorías como objeto
            return selectedCategory ? postCategories.some((category) => category.name === selectedCategory) : true;
          /*   console.log("Post:", post);
            console.log("Categories:", postCategories);
            console.log("Should Display:", shouldDisplay);
            return shouldDisplay; */
          })
          .map((post) => (

              <Link to={`/blog/${post.slug}`} key={post.slug} className="card-link">
                <ul className="rounded-xl overflow-hidden border text-left h-full">
              <img
                className="h-[17rem] w-full object-cover"
                src={post.cover}
                alt={post.title}
              />
              <li className='my-6 flex flex-col gap-1'>
              <p className="mx-4 flex justify-between font-normal">
                {" "}
              
                <span >
                {moment(post.published).format("ll")}
                </span>{" "}
                &middot;
                &middot;
                <span className="mx-1">{post.reading_time} min read</span>
              </p>{" "}
              <h3 id={`title` + post.id} className="mx-4 text-lg">
              {post.title.length > 34
                      ? post.title.slice(0, 33)
                      : post.title}              
                      </h3>
                      </li>
            </ul>
          </Link>
          ))}
      </section>
    </main>
  );
}

export default BlogList;
