import Modal from 'react-modal';
import { X } from 'lucide-react';
Modal.setAppElement('#root');

const ModalCheck = ({ isOpen, onRequestClose }) => {
  return (
    <Modal
      isOpen={isOpen}
      onRequestClose={onRequestClose}
      appElement={document.getElementById('root')}
      className="
       w-full h-full relative flex justify-center items-center border-0 focus:border-0"
       >
       <button onClick={onRequestClose} className='absolute top-4 right-4 rounded-lg border bg-white p-2'><X className='w-7 h-7'/></button>
      <div className=''>
        <iframe
          width="860"
          height="520"
          className='rounded-xl'
          src="https://www.youtube.com/embed/ZgPFMFaMuBI"
          title="YouTube video player"
          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
          allowFullScreen
        ></iframe>
      </div>
    </Modal>
  );
}

export default ModalCheck;
