import axios from "axios";
import Navbar from "components/navigation/Navbar";
import Footer from "components/navigation/Footer";
import Layout from "hocs/layouts/Layout";
import { useEffect, useState } from "react";
import { Helmet } from "react-helmet-async";
import { useParams } from "react-router-dom";
import moment from "moment";
import DomPurify from "dompurify";
import { Link } from "react-router-dom";
import { FaLinkedinIn, FaMeta, FaXTwitter } from "react-icons/fa6";
import { IoArrowRedoCircle } from "react-icons/io5";

function NewsDetails() {
  const { slug } = useParams(); // Obtener el slug de la URL
  const [newsDetail, setNewsDetail] = useState({});
  axios.defaults.withCredentials = true;
  const [hasVoted, setHasVoted] = useState(false); // New state for tracking if the user has voted

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await axios.get(`${process.env.REACT_APP_API_URL_2}/api/news/details/${slug}`, { withCredentials: true });
        setNewsDetail(response.data);
      } catch (error) {
        console.error('Error fetching news detail:', error);
      }
    };

    fetchData();
  }, [slug]);
  
  const contentSections = newsDetail.content_sections || [];

  const handleVote = async (choice) => {
    if (!hasVoted) {
      try {
        // Make the POST request to vote
        await axios.post(`${process.env.REACT_APP_API_URL_2}/api/news/details/${slug}`, { vote: choice }, { withCredentials: true });
        
        // Update the state to reflect that the user has voted
        setHasVoted(true);
      } catch (error) {
        console.error('Error submitting vote:', error);
      }
    }
  };
  

  return (
    <Layout>
      <Helmet>
        <title>{newsDetail ? newsDetail.title : "Loading..."}</title>
        <meta
          name="description"
          content={
            newsDetail
              ? newsDetail.description
              : "Our news are carefully curated by our editors and our popular content writers. We also invite guest writers from other companies, startups, and partners."
          }
        />
        <meta name="robots" content="index" />
        <link
          rel="canonical"
          href={
            newsDetail ? `https://www.clous.app/news-room/${newsDetail.slug}/` : ""
          }
        />
        <meta name="author" content={"Clous"} />
        <meta name="publisher" content="Clous" />
        <meta
          property="og:url"
          content={
            newsDetail ? `https://www.clous.app/news-room/${newsDetail.slug}/` : ""
          }
        />
        <meta property="og:type" content="website" />
        <meta
          property="og:title"
          content={newsDetail ? newsDetail.title : "Loading..."}
        />
        <meta
          property="og:description"
          content={
            newsDetail
              ? newsDetail.description
              : "Our news are carefully curated by our editors and our popular content writers. We also invite guest writers from other companies, startups, and partners."
          }
        />
        <meta
          property="og:image"
          content={newsDetail ? newsDetail.thumbnail : 'https://clous.s3.eu-west-3.amazonaws.com/images/ClousPeer.webp'}
        />
        <meta name="twitter:card" content="summary_large_image" />
        <meta
          name="twitter:title"
          content={newsDetail ? newsDetail.title : "Loading..."}
        />
        <meta
          name="twitter:description"
          content={
            newsDetail
              ? newsDetail.description
              : "Our news are carefully curated by our editors and our popular content writers. We also invite guest writers from other companies, startups, and partners."
          }
        />
        <meta
          name="twitter:image"
          content={newsDetail ? newsDetail.thumbnail : 'https://clous.s3.eu-west-3.amazonaws.com/images/ClousPeer.webp'}
        />
      </Helmet>
      <section className="bg-[#FAFAFA]  text-dark-blue-greenish text-sm font-semibold px-4 sm:px-6 xl:px-16 2xl:px-24 flex-wrap w-full fixed z-30  ">
        <Navbar />
      </section>
    
      {newsDetail ? (
          <main className="pt-24 mb-24" key={newsDetail.slug}>
            <section className="relative">
              <p className="absolute inset-0 bg-gray-500">
                <img
                  className="h-full w-full object-cover mix-blend-multiply"
                  src={newsDetail.cover}
                  alt={newsDetail.title}
                />
              </p>
              <div className="relative max-w-4xl mx-auto py-24">
                <h1
                  className="text-4xl font-bold tracking-tight text-white
            sm:text-5xl lg:text-6xl"
                >
                  {" "}
                  {newsDetail.title}
                </h1>
                <p className="text-sm font-medium text-white">
                  <span className=" mt-2 ml-2 mr-1">
                    {moment(newsDetail.published).format("ll")}
                  </span>{" "}
                  &middot;
                  <span className="mx-2 mt-2">{newsDetail.reading_time} min read</span>
                </p>
              </div>
            </section>
            <section className=" mt-12 text-dark-blue-greenish flex justify-center">
              <div id="detail" className="max-w-4xl">
                <ul className=" flex mb-4 gap-4">
                  <li className="flex gap-2 items-start">
                    <img
                      src={newsDetail.author_profile?.avatar}
                      className="w-12 h-12  rounded-full"
                      alt="Alvaro Clous CEO"
                    />
                    <div className="flex-col flex text-sm ">
                      <span className="text-xl font-semibold">
                        {newsDetail.first_name} {newsDetail.last_name}
                      </span>
                      <span>{newsDetail.author_profile?.position}</span>
               <div className="flex">

                    <Link
                      to={newsDetail.author_profile?.linkedin}
                      rel="follow"
                      target="_blank"
                      className="text-dark-blue-greenish transition hover:text-button-orange"
                      >
                      <FaLinkedinIn className="w-6 h-6" />
                    </Link>
                    <Link
                      to={newsDetail.author_profile?.twitter}
                      rel="follow"
                      target="_blank"
                      className="text-dark-blue-greenish transition hover:text-button-orange"
                      >
                      <FaXTwitter className="w-6 h-6" />
                    </Link>
                      </div>
                        </div>
                  </li>
                </ul>
                <div className="flex flex-col gap-8 pt-8">
                <p
                  dangerouslySetInnerHTML={{
                    __html: DomPurify.sanitize(newsDetail.introduction),
                  }}
                />
            <div>
                {contentSections.map((section, index) => (
                  <div key={index} className="flex flex-col gap-6">
                    <h2>{section.heading}</h2>
                    <div dangerouslySetInnerHTML={{ __html: section.content }} className=" mb-12"/>
                    <img src={section.image} alt={section.heading} className="rounded-xl"/>
                  </div>
                ))}
              </div>
                </div>
              </div>
              <aside className="sticky top-20 h-40 -mr-8 flex flex-col gap-2">
              <Link
                      to="https://www.linkedin.com/company/92962421/admin/feed/posts/"
                      rel="follow"
                      target="_blank"
                      className="text-dark-blue-greenish transition hover:text-button-orange"
                    >
                      <FaLinkedinIn className="w-6 h-6" />
                    </Link>   
                    <Link
                      to="https://twitter.com/cloushq"
                      rel="follow"
                      target="_blank"
                      className="text-dark-blue-greenish transition hover:text-button-orange"
                    >
                    <FaXTwitter className="w-6 h-6" />
                    </Link> 
                    <Link
                      to="/"
                      rel="follow"
                      target="_blank"
                      className="text-dark-blue-greenish transition hover:text-button-orange"
                    >
                <FaMeta className="w-6 h-6" />
                    </Link>               
                              
                <IoArrowRedoCircle className="w-6 h-6" />
              </aside>
            </section>
            <section className="max-w-4xl mx-auto py-12 flex">
            <p
                  dangerouslySetInnerHTML={{
                    __html: DomPurify.sanitize(newsDetail.introduction),
                  }}
                />
            </section>
            <section className="max-w-4xl mx-auto">
           
              <h1 className="text-5xl font-semibold">Was this helpfull ?</h1>
              <div className="flex gap-3 mt-4">
              <button
            onClick={() => handleVote('yes')}
            className={`border rounded-lg px-3 py-1.5 bg-primary text-white font-semibold ${hasVoted ? 'opacity-50 cursor-not-allowed' : ''}`}
            disabled={hasVoted}
          >
            Yes
          </button>
          <button
            onClick={() => handleVote('no')}
            className={`border rounded-lg px-3 py-1.5 bg-main-white text-primary font-semibold ${hasVoted ? 'opacity-50 cursor-not-allowed' : ''}`}
            disabled={hasVoted}
          >
            No
          </button>

              </div>
            </section>
          </main>
         ) : (
        <p>Loading...</p>
      )}
      <Footer />
    </Layout>
  );
}

export default NewsDetails;
