import mixpanel from "mixpanel-browser";
import { IoPlayCircle } from "react-icons/io5";
import ModalCheck from '../../ui/Modal';
import NormalButton from "../../ui/NormalButton";

function HeroMision({modalIsOpen, setModalIsOpen}) {
  const trackButtonClick = (Property) => {
    mixpanel.track('External Link', {
    Name : Property,
    Property: Property, });
  };

  
  const openModal = () => {
    // ... Lógica para abrir el modal ...
    setModalIsOpen(true);
  };

  const closeModal = () => {
    // ... Lógica para cerrar el modal ...
    setModalIsOpen(false);
  };
  return (
    <section className="py-16 max-w-8xl relative overflow-hidden lg:flex justify-between gap-8">
        <div className="mx-autotext-dark-blue-greenish lg:flex-auto text-left">
          <h1 className="font-bold text-4xl lg:text-7xl">
          Our commitment with talent
          </h1>
          <p className="my-2 text-lg lg:text-xl font-normal pr-20">
            We have developed the Clous Manifestos as a representation of our cultural values since our foundation.
          </p>
          <div className="grid md:flex items-center gap-4 text-lg mt-4">

          <NormalButton name="Try our Beta" onClick={() => trackButtonClick("Demo")}  linkUrl="https://demo.clous.app"/>
        <div onClick={openModal} className="flex gap-2 items-center cursor-pointer">
          <IoPlayCircle className="w-5 h-5"/> Watch our demo
        </div>
      </div>
        </div>
        <img
            className="rounded-lg"
            width={640}
            src="https://clous.s3.eu-west-3.amazonaws.com/images/openings.webp"
            alt="Clous Manifestos by Clous"/>

<ModalCheck
        isOpen={modalIsOpen}
        onRequestClose={closeModal}
        />
    </section>
  );
}

export default HeroMision;