import { Link } from "react-router-dom";
import mixpanel from "mixpanel-browser";

function TrustedMedia() {
  const trackButtonClick = (buttonName) => {
    mixpanel.track(`Link ${buttonName}`);
  }
  return (
    <main className='pb-16 text-center'>
      <h3 className='text-xl font-normal pb-8 text-gray-500'>Featured in</h3>
      <section className='flex md:justify-center lg:gap-16 gap-8 items-center overflow-auto '>
      <Link to="https://999plazaradio.es/queremos-ocupar-el-lugar-de-las-flores-como-regalo-de-los-momentos-mas-especiales-jorge-sanchez-responsable-de-comunicacion-de-pancracio-chocolates-agencia-kids1"
      onClick={() => trackButtonClick(" - Plazaradio")}
      >
      <img width={150} src="https://clous.s3.eu-west-3.amazonaws.com/images/logos/logo_plazaradio.png" alt="Plazaradio partner Clous"/>
      </Link>
      <Link to="https://elreferente.es/startup/clous/"
        onClick={() => trackButtonClick(" - Elreferente")}
      >
      <img width={150} src="https://clous.s3.eu-west-3.amazonaws.com/images/logos/logo_elreferente.png" alt="Elreferente Clous Partner" 
      />  
      </Link>
      <Link className="https://emprendedores.es/ayudas/lanzadera-3/"
        onClick={() => trackButtonClick(" - Emprendedores")}
      >
      <img width={150} src="https://clous.s3.eu-west-3.amazonaws.com/images/logos/logo_emprendedores.png" alt="Clous Parnter Emprendedores"
      />
      </Link>
      <Link to="https://www.abc.es/espana/comunidad-valenciana/lanzadera-potencia-programa-aceleracion-selecciona-100-empresas-20230904112606-nt.html"
              onClick={() => trackButtonClick(" - Diario ABC")}
      >
      <img width={80} src="https://clous.s3.eu-west-3.amazonaws.com/images/logos/logo_diario_abc.png" alt="Clous Parnter Diario ABC"/>
      </Link>

      </section>
    </main>
  )
}

export default TrustedMedia