import { Link } from "react-router-dom";
import { useEffect, useState } from "react";
import moment from "moment";
import axios from "axios";

function NewsList() {
  const [newsList, setNewsList] = useState([]);
  axios.defaults.withCredentials = true;

  // Realiza la solicitud GET con las credenciales
  useEffect(() => {

    const fetchData = async () => {
      try {
        const response = await axios.get(`${process.env.REACT_APP_API_URL_2}/api/news/list`, { withCredentials: true });
        setNewsList(response.data);
      } catch (error) {
        console.error('Error fetching news:', error);
      }
    };

    fetchData();
  }, []); // El segundo parámetro [] significa que useEffect se ejecutará solo una vez al montar el componente

  return (
    <main>
       <section className="grid md:grid-cols-2 xl:grid-cols-3 gap-8">
        {newsList &&
          newsList.map((post) => (
     
            <Link
            to={`/news-room/${post.slug}`}
            key={post.slug}
            className="card-link"
          >
        
            <ul className="rounded-xl overflow-hidden border text-left h-full">
              <img
                className="h-[17rem] w-full object-cover"
                src={post.cover}
                alt={post.title}
              />
              <li className='my-6 flex flex-col gap-1'>
              <p className="mx-4 flex justify-between font-normal">
                {" "}
              
                <span >
                {moment(post.published).format("ll")}
                </span>{" "}
                &middot;
                &middot;
                <span className="mx-1">{post.reading_time} min read</span>
              </p>{" "}
              <h3 id={`title` + post.id} className="mx-4 text-lg">
              {post.title.length > 34
                      ? post.title.slice(0, 33)
                      : post.title}              
                      </h3>
                      </li>
            </ul>
          </Link>
          ))}
      </section>
    </main>
  );
}

export default NewsList;
