import { Input } from "@material-tailwind/react";
import { useState } from "react";
import React from "react";

const Qoute = () => {

    const [formData, setFormData] = useState({
      first: "",
      last: "",
      email: "",
      hires: "",
      message: "",
      company: "",
    });
    const { first, last, email, hires, message, company } = formData;
  
    const onChange = (e) => {
      setFormData({ ...formData, [e.target.first]: e.target.value });
    };
  
    const onSubmit = (e) => {
      e.preventDefault();
  
      const newFormData = new FormData();
      newFormData.append("first", first);
      newFormData.append("last", last);
      newFormData.append("email", email);
      newFormData.append("hires", hires);
      newFormData.append("message", message);
      newFormData.append("company", company);
    };

    return (
      <main>

        <section className="flex item-center justify-center pr-12">
          <form
            className="space-y-2 w-[27rem]"
            onSubmit={(e) => {
              onSubmit(e);
            }}
          >
            <div className="flex gap-4">

            <Input
              className="focus:outline-none placeholder-shown:border-t-primary placeholder-shown:border-primary"
              id="first-name"
              name="first name"
              value={first}
              onChange={(e) => onChange(e)}
              type="text"
              required
              label="First name"
              color="orange"
              />{" "}
            <Input
              className="focus:outline-none placeholder-shown:border-t-primary placeholder-shown:border-primary"
              id="last-name"
              name="last name"
              value={last}
              onChange={(e) => onChange(e)}
              type="text"
              required
              label="Last name"
              color="orange"
              />{" "}
              </div>
              <Input
              className="focus:outline-none placeholder-shown:border-t-primary placeholder-shown:border-primary"
              id="email-address"
              name="email"
              value={email}
              onChange={(e) => onChange(e)}
              type="email"
              required
              label="Company email address"
              color="primary"
              />{" "}
            
   
          </form>
        </section>
        <section>

        </section>
      </main>
    
   );
}
 
export default Qoute;