import mixpanel from "mixpanel-browser";
import { Link } from "react-router-dom";
import React from "react";
import TextButton from "../../ui/TextButton";
import NormalButton from "../../ui/NormalButton";

export default function HeroPartner() {
  const trackButtonClick = (Property) => {
    mixpanel.track('External Link', {
    Name : Property,
    Property: Property, });
  }; 
  return (
    <section className="lg:flex py-16 justify-between gap-8">
      <div className="overflow-hidden text-left">
        <h1 className="font-bold text-5xl lg:text-7xl">
          Driving innovation together{" "}
        </h1>
        <p className="my-2 font-normal text-lg lg:text-xl">
          We believe that collaboration is the key to unlocking limitless
          opportunities. Become our valued partner and embark on a journey
          of shared success.
        </p>
        
        <div className="grid md:flex mt-4 items-center gap-4 text-lg">
 
 <NormalButton name="Try our Beta" linkUrl="https://demo.clous.app"
     onClick={() => trackButtonClick("Demo")}/>

        <Link 
              className="inline-flex text-primary"

              to="/partners#programs"
               >
              
              <TextButton name="Join our programs"/>
            </Link>
      </div>
      </div>
    
        <img
        width={640}
          className="rounded-lg lg:block hidden"
          src="https://clous.s3.eu-west-3.amazonaws.com/images/ClousPeer.webp"
          alt="Clous Partnerships to Thrive as Organizations"
        />
    
    </section>
  );
}