import React from 'react';
import { useCookies } from 'react-cookie';
import { Link } from 'react-router-dom';

const CookieBanner = () => {
  const [cookies, setCookie] = useCookies(['cookieConsent']);

  const handleAccept = () => {
    setCookie('cookieConsent', true, { path: '/' });
  };


  if (cookies.cookieConsent) {
    return null; // Don't render the banner if the cookieConsent is set
  }

  return (
    <main className="flex sm:justify-center ">
       <section className=' bg-dark-blue-greenish fixed bottom-0 z-40 items-center md:text-lg my-2 md:p-8 p-4 rounded-xl flex'>
      <p className="font-regular text-white">
          You agree to cookies by being here,{" "}
          <Link className='text-button-orange' to={"/privacy"}

          > read policy.</Link>
        </p>
        <button className='text-white pl-5 hover:text-button-orange' onClick={() => handleAccept()}>Accept</button>

      </section>
     
    </main>
  );
};
export default CookieBanner;