import Navbar from "components/navigation/Navbar";
import Footer from "components/navigation/Footer";
import Layout from "hocs/layouts/Layout";
import { Helmet } from "react-helmet-async";
import { useEffect, useState } from "react";
import MeetingBand from "components/conect/MeetingBand";
import FooterBand from "components/navigation/FooterBand";
import icon from "assets/img/favicon.png";
import Uds from "components/product/cloush/Uds";
import Programs from "../../../components/others/Programs";
import HeroClous from "../../../components/product/cloush/HeroClous";
import SectionX from "../../../components/product/cloush/SectionX";
import mixpanel from "mixpanel-browser";
import TabsSectionI from "../../../components/product/cloush/TabsSectionI";

function ClousH() {
  const [modalIsOpen, setModalIsOpen] = useState(false);

  useEffect(() => {
    window.scrollTo(0, 0);
    mixpanel.track("ClousH Page", {

    });
  }, []);
  return (
    <Layout>
      <Helmet>
        <title>
          Hiring technology with AI for businesses - Clous
        </title>
        <meta
          name="description"
          content="We develop hiring software technology to help startups  improve the quality of their hiring processes. Hire faster with our first product ClousH."
        />

        <meta name="robots" content="index, follow" />
        <link rel="icon" content={icon} />
        <meta name="author" content="Clous Technology SL" />
        <meta name="publisher" content="Clous" />
        <meta property="og:image" content='https://clous.s3.eu-west-3.amazonaws.com/images/ClousPeer.webp' />

        <meta property="og:url" content="https://www.clous.app/cloush/" />
        <meta property="og:type" content="website" />
        <meta
          property="og:title"
          content="Hiring technology with AI for businesses - Clous"
        />
        <meta
          property="og:description"
          content="We develop hiring software technology to help startups  improve the quality of their hiring processes. Hire faster with our first product ClousH."
        />

        <meta name="twitter:card" content="summary_large_image" />
        <meta
          name="twitter:title"
          content="Hiring technology with AI for businesses - Clous"
        />

        <meta
          name="twitter:description"
          content="We develop hiring software technology to help startups  improve the quality of their hiring processes. Hire faster with our first product ClousH."
        />
        <meta name="twitter:image" content="https://clous.s3.eu-west-3.amazonaws.com/images/ClousPeer.webp" />
      </Helmet>
      <div className="bg-[#FAFAFA] text-dark-blue-greenish text-sm font-semibold max-w-8xl px-4 sm:px-6 xl:px-16 2xl:px-24 flex-wrap w-full fixed z-30  ">
      {!modalIsOpen && <Navbar />}
      </div>
      <header className="bg-[#FAFAFA] text-dark-blue-greenish text-sm font-semibold pt-24 mx-auto max-w-8xl px-4 sm:px-6 xl:px-16 2xl:px-24">
      <HeroClous modalIsOpen={modalIsOpen} setModalIsOpen={setModalIsOpen}/>
       </header>
      <main className="bg-[#FAFAFA] text-dark-blue-greenish text-sm font-semibold mx-auto max-w-8xl px-4 sm:px-6 xl:px-16 2xl:px-24">
        <MeetingBand />
        {/*       <SectionIII /> */}
        <Programs/>
        <Uds />
<SectionX/>
        <TabsSectionI />
        <FooterBand />
      </main>

      <Footer />
    </Layout>
  );
}
export default ClousH;
